package com.eventdrivencommerce.inventory.infrastructure.outbox;
import org.apache.kafka.clients.producer.ProducerRecord;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.concurrent.TimeUnit;
@Component @ConditionalOnProperty(name="inventory.outbox.publisher-enabled",havingValue="true",matchIfMissing=true) public class OutboxPublisher {
 private final SpringDataOutboxRepository repository;private final KafkaTemplate<String,String> kafka;private final Clock clock;private final String topic;private final int batch;private final Duration timeout;
 public OutboxPublisher(SpringDataOutboxRepository repository,KafkaTemplate<String,String> kafka,Clock clock,@Value("${inventory.outbox.topic}")String topic,@Value("${inventory.outbox.batch-size:50}")int batch,@Value("${inventory.outbox.publish-timeout:PT10S}")Duration timeout){this.repository=repository;this.kafka=kafka;this.clock=clock;this.topic=topic;this.batch=batch;this.timeout=timeout;}
 @Scheduled(fixedDelayString="${inventory.outbox.poll-interval:PT1S}")@Transactional public void publish(){for(var e:repository.lockPending(batch)){try{var r=new ProducerRecord<String,String>(topic,e.aggregateId.toString(),e.payload.toString());header(r,"eventId",e.eventId.toString());header(r,"eventType",e.eventType);header(r,"eventVersion","1");header(r,"correlationId",e.correlationId.toString());header(r,"causationId",e.causationId.toString());header(r,"contentType","application/json");header(r,"schema",schema(e.eventType));header(r,"producer","inventory-service");kafka.send(r).get(timeout.toMillis(), TimeUnit.MILLISECONDS);e.published(clock.instant());}catch(Exception ex){e.failed(clock.instant(),root(ex));}}}
 private static String schema(String type){return "InventoryReservedV1".equals(type)?"inventory-reserved-v1.schema.json":"inventory-reservation-failed-v1.schema.json";}private static void header(ProducerRecord<String,String>r,String n,String v){r.headers().add(n,v.getBytes(StandardCharsets.UTF_8));}private static String root(Exception e){Throwable t=e;while(t.getCause()!=null)t=t.getCause();return t.getMessage();}
}
